-- Identity resolution does not clear unrelated business attention; the worker clears its own Quibi reason.
do $migration$ declare definition text; begin select pg_get_functiondef('public.resolve_case_vehicle(uuid,uuid,text,uuid,timestamptz,jsonb,jsonb)'::regprocedure) into definition; if position('set customer_id=canonical.id,attention_needed=false,attention_reason=null' in definition)=0 then raise exception 'UNEXPECTED_CANONICAL_RESOLVER'; end if; definition:=replace(definition,'set customer_id=canonical.id,attention_needed=false,attention_reason=null','set customer_id=canonical.id'); execute definition; end $migration$;
